import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&icon_names=arrow_back_ios" />

import "./Product.css";

export function Product() {
  const { id } = useParams();
  const [each, setEach] = useState([]);
  useEffect(() => {
    fetch(`https://fakestoreapi.com/products/${id}`)
      .then((res) => res.json())
      .then((res) => setEach([res]));
  }, [id]);

  console.log(each);

  return (
    <div>
      {each.map((elm) => {
        return (
          <div key={elm.id} className="mainBox">
            <img src={elm.image} alt="product" />
            <div className="data">
              <h2>{elm.title}</h2>
              <h3>
                Category: <span>{elm.category}</span>
              </h3>
              <p>{elm.description}</p>
              <p className="price">${elm.price}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}
